mapper.select:
select * from ( select
from rep_prod_info rpi where 1=1 and rpi.rep_prod_type ='02' UNION ALL select
from rep_prod_info rpi left join rep_prod_info prpi on prpi.prod_id = rpi.p_prod_id where 1=1 and rpi.rep_prod_type ='03' ) temp where 1=1
AND temp.P_PROD_ID LIKE concat('%',concat(#{prodId,jdbcType=VARCHAR},'%'))
AND temp.PROD_ID IN
#{item}
AND temp.STATUS IN
#{item}
AND temp.PROD_RE IN
#{item}
AND temp.RAISE_TYPE IN
#{item}
AND temp.is_grade IN
#{item}
AND temp.PROFIT_TYPE IN
#{item}
AND temp.RAISE_STRDATE >= TO_DATE(#{raiseStrdateStart},'YYYY-MM-DD')
AND temp.RAISE_STRDATE <= TO_DATE(#{raiseStrdateEnd},'YYYY-MM-DD')
AND temp.RAISE_ENDDATE >= TO_DATE(#{raiseStrdateStart},'YYYY-MM-DD')
AND temp.RAISE_ENDDATE <= TO_DATE(#{raiseStrdateEnd},'YYYY-MM-DD')
/*NYLCXP-975 产品成立日查询条件取值有误,应该是查母产品的成立日 add by zhouqiang start*/
AND temp.pSetDate >= TO_DATE(#{setDateStart},'YYYY-MM-DD')
AND temp.pSetDate <= TO_DATE(#{setDateEnd},'YYYY-MM-DD')
/*NYLCXP-975 产品成立日查询条件取值有误,应该是查母产品的成立日 add by zhouqiang end*/ order by NVL(temp.UPDATE_TIME,temp.CREATE_TIME) desc

